class OntologyConflict(BaseModel):
    """
    A current-data conflict found while previewing a subtractive ontology change.
    Reported back so the caller can decide whether to re-run with
    `allow_data_conflicts` (which keeps the affected records — Little Big Brain never
    rewrites or drops them — and applies the change in warn mode).
    """

    affected: Annotated[
        int,
        Field(
            description='How many current records the change would orphan/flag.', ge=0
        ),
    ]
    kind: Annotated[
        str,
        Field(
            description='`entities_of_removed_type` | `edges_of_removed_relation` |\n`edges_outside_narrowed_domain` | `edges_outside_narrowed_range` |\n`property_values_outside_constraint` | `relation_cardinality`.'
        ),
    ]
    message: str
    samples: Annotated[
        list[str] | None,
        Field(
            description='Bounded deterministic examples. `affected` remains the exact count.'
        ),
    ] = None
    subject: Annotated[
        str,
        Field(
            description='`class:<stable_id>` or `relation:<stable_id>` the conflict is about.'
        ),
    ]


