class OntologyDefineRequest(BaseModel):
    """
    Define the scoped graph's ontology. Imports `source` (any
    [`crate`]-supported format), optionally merges the built-in default so the
    standard entity types/relations stay available, and creates the graph head
    with the result.

    The call is re-runnable on a graph that already exists. An unchanged
    ontology is a no-op; an additive difference is applied, including a widened
    relation domain or range and a new property field; a narrowing or removing
    difference is refused with a typed error naming the route that applies it.
    """

    dry_run: Annotated[
        bool | None,
        Field(
            description='Preview the exact definition without creating a graph, writing an\nontology object, or changing the graph head. Equivalent to the\n`?dry_run=true` query parameter; either signal enables preview mode.'
        ),
    ] = None
    format: Annotated[
        str | None,
        Field(
            description='Import format hint. `auto` (the default) sniffs the content.'
        ),
    ] = None
    merge_default: Annotated[
        bool | None,
        Field(
            description='Merge the built-in `default_ai_context_ontology()` underneath the\nimported types so the standard AI-context vocabulary stays available.'
        ),
    ] = None
    source: Annotated[
        str,
        Field(
            description='Ontology document text: Little Big Brain JSON, JSON-LD, Turtle/N3, RDF/XML, or\nCSV/TSV. Detected from `format` (default `auto`).'
        ),
    ]


